mapper.select:
select *
from real_time_evaluation rte


        and unit_id = #{unitId}


        and create_time > #{startDate}


        and create_time <= #{endDate}


limit 20

select bt.standard_value as benchmarkValue,ot.standard_value as realVule,ot.result_number,ot.evaluation_id from object_target ot left join benchmark_target bt on bt.evaluation_id=ot.evaluation_id and bt.model_id=ot.model_id  where ot.evaluation_id =#{evaluationId} and ot.model_id =#{modelId}
union
select bt.standard_value as benchmarkValue,ot.standard_value as realVule,ot.result_number,ot.evaluation_id from object_range ot left join benchmark_range bt on bt.evaluation_id=ot.evaluation_id and bt.model_id=ot.model_id  where ot.evaluation_id =#{evaluationId} and ot.model_id =#{modelId}
union
select bt.standard_value as benchmarkValue,ot.standard_value as realVule,ot.result_number,ot.evaluation_id from object_factor ot left join benchmark_factor bt on bt.evaluation_id=ot.evaluation_id and bt.model_id=ot.model_id  where ot.evaluation_id =#{evaluationId} and ot.model_id =#{modelId}

SELECT id
FROM real_time_evaluation
WHERE create_time < (
SELECT create_time
FROM real_time_evaluation
WHERE id = #{evaluationId}
)
AND benchmark_instance_id not in (
SELECT benchmark_instance_id
FROM real_time_evaluation
WHERE id = #{evaluationId}
)
ORDER BY create_time DESC
LIMIT 1;
